records=[]
for key,name,author,title,year,url,opened,use,hyp in data:
 f=CACHE/(name+'.pdf')
 records.append(dict(citation_key=key,author=author,title=title,year=year,url=url,local_source=str(f.relative_to(ROOT)),source_sha256=hashlib.sha256(f.read_bytes()).hexdigest(),status='verified_for_stated_use',opened_locator=opened,actual_use=use,hypotheses_and_normalization_check=hyp,checker='GPT-6 Astra (OpenAI, ChatGPT Pro mode)',effort='Pro',date='2026-11-17 UTC'))
