old=json.loads(oldpath.read_text()) if oldpath.exists() else []
newkeys={r['citation_key'] for r in records}
oldpath.write_text(json.dumps(records+[r for r in old if r['citation_key'] not in newkeys],ensure_ascii=False,indent=2)+'\n')
# Source metadata are retained, but inherited verification claims are replaced by our actual scope.
bib=(ROOT/'sources/returns/S6_04_MAPS_MANIFOLDS/S6_04_MAPS_MANIFOLDS_references.bib').read_text()
blocks=[]
for match in re.finditer(r'(?ms)^@\w+\{([^,]+),.*?(?=^@|\Z)',bib):
 if match.group(1) in newkeys:
  s=match.group(0).strip()
  s=re.sub(r'(?s),?\s*note\s*=\s*\{.*\}\s*\}', '\n}', s)
  s=s.replace('author={Kazuki Fukae}','author={Mitsuaki Fukae}')
  blocks.append(s)
(OUT/'maps_D_checked_references.bib').write_text('\n\n'.join(blocks)+'\n')
print('Saved eight scoped original-source records and bibliography corrections.')
